// Function to update the block list from a remote server
void update_block_list() {
    int sockfd, n;
    struct sockaddr_in server_addr;
    char buffer[1024];

    // Create a socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        exit(1);
    }

    // Set up the server address structure
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = inet_addr(REMOTE_SERVER);

    // Connect to the remote server
    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to server");
        close(sockfd);
        exit(1);
    }

    // Receive the block list from the server
    n = recv(sockfd, buffer, sizeof(buffer), 0);
    if (n > 0) {
        buffer[n] = '\0';
        // Parse the block list
        char *token = strtok(buffer, "\n");
        int i = 0;
        while (token != NULL) {
            strcpy(block_list[i], token);
            i++;
            token = strtok(NULL, "\n");
        }
    }

    // Close the socket
    close(sockfd);
}

