// Function to check if a user is in a specific group
int is_user_in_group(const char *username, const char *groupname) {
    struct passwd *pwd;
    struct group *grp;
    char *token;
    char *line;
    FILE *fp;

    pwd = getpwnam(username);
    if (!pwd) {
        return 0;
    }

    fp = fopen("/etc/group", "r");
    if (!fp) {
        return 0;
    }

    while ((line = fgets(fp, 1024, fp)) != NULL) {
        token = strtok(line, ":");
        if (token == NULL) {
            continue;
        }

        if (strcmp(token, groupname) == 0) {
            fclose(fp);
            return 1;
        }
    }

    fclose(fp);
    return 0;
}

// Function to check if a user has write access to a directory
int has_write_access(const char *username, const char *dirname) {
    struct passwd *pwd;
    struct stat st;
    char *token;
    char *line;
    FILE *fp;

    pwd = getpwnam(username);
    if (!pwd) {
        return 0;
    }

    if (stat(dirname, &st) == -1) {
        return 0;
    }

    if (S_ISDIR(st.st_mode)) {
        // Check if the user has write access to the directory
        if (st.st_uid == pwd->pw_uid) {
            return 1;
        }

        // Check if the user is in a group that has write access
        fp = fopen("/etc/group", "r");
        if (!fp) {
            return 0;
        }

        while ((line = fgets(fp, 1024, fp)) != NULL) {
            token = strtok(line, ":");
            if (token == NULL) {
                continue;
            }

            if (strcmp(token, "www-data") == 0) {
                fclose(fp);
                return 1;
            }
        }

        fclose(fp);
    }

    return 0;
}

