// Function to check if an IP address is in a given CIDR range
int is_in_cidr(char *ip, char *cidr) {
    struct in_addr addr;
    struct in_addr cidr_addr;
    int prefix_len;
    int i;

    // Parse the CIDR range
    char *slash = strchr(cidr, '/');
    if (!slash) {
        return 0;
    }
    prefix_len = atoi(slash + 1);
    *slash = '\0';

    // Convert the IP address to a 32-bit integer
    addr.s_addr = inet_addr(ip);
    if (addr.s_addr == INADDR_NONE) {
        return 0;
    }

    // Convert the CIDR range to a 32-bit integer
    cidr_addr.s_addr = inet_addr(cidr);
    if (cidr_addr.s_addr == INADDR_NONE) {
        return 0;
    }

    // Check if the IP address is in the CIDR range
    unsigned long long ip_int = addr.s_addr;
    unsigned long long cidr_int = cidr_addr.s_addr;
    unsigned long long mask = 0xFFFFFFFFUL << (32 - prefix_len);

    return ((ip_int & mask) == (cidr_int & mask));
}

