// Function to block access to the directory
void block_directory_access(char* directory_path) {
    // Create a lock file in the directory to prevent access
    char lock_file[256];
    snprintf(lock_file, sizeof(lock_file), "%s/.lock", directory_path);

    int lock_fd = open(lock_file, O_CREAT | O_WRONLY, 0600);
    if (lock_fd == -1) {
        perror("Error creating lock file");
        exit(EXIT_FAILURE);
    }

    // Write a simple lock message to the file
    char lock_message[] = "Access blocked by system";
    write(lock_fd, lock_message, strlen(lock_message));
    close(lock_fd);

    printf("Access to directory %s has been blocked.\n", directory_path);
}

// Function to check if a user is trying to access the directory
int check_access_attempt(char* username, char* directory_path) {
    // In this example, we'll simply check if the username is "admin"
    if (is_authorized(username)) {
        return 1; // Authorized user
    } else {
        return 0; // Unauthorized user
    }
}

