#define LOG_FILE "/var/log/directory_access.log"
#define BLOCKED_DIR "/restricted"

void log_access(const char *username, const char *ip_address) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s %s %s\n", username, ip_address, ctime(&time(NULL)));
        fclose(log_file);
    }
}

int main() {
    struct stat sb;
    char buffer[1024];
    int pid;

    // Check if the directory exists
    if (stat(BLOCKED_DIR, &sb) == -1) {
        perror("Directory does not exist");
        exit(EXIT_FAILURE);
    }

    // Create a child process to monitor access attempts
    pid = fork();
    if (pid == 0) {
        // Child process: monitor directory access
        while (1) {
            // Check if any process is accessing the directory
            if (stat(BLOCKED_DIR, &sb) == 0) {
                // Directory exists, so it's being accessed
                log_access("unknown", "unknown");
                // Block access by removing the directory
                unlink(BLOCKED_DIR);
                exit(EXIT_SUCCESS);
            }
            sleep(1);
        }
    } else {
        // Parent process: continue normal operations
        while (1) {
            // Check if the directory exists
            if (stat(BLOCKED_DIR, &sb) == 0) {
                // Directory exists, so it's being accessed
                log_access("unknown", "unknown");
                // Block access by removing the directory
                unlink(BLOCKED_DIR);
                exit(EXIT_SUCCESS);
            }
            sleep(1);
        }
    }

    return 0;
}

