// Function to check if an IP address is within a CIDR range
int is_ip_in_cidr(char *ip, char *cidr) {
    struct in_addr addr;
    struct in_addr cidr_addr;
    int prefix_len;
    int result;

    // Convert IP address to network byte order
    inet_aton(ip, &addr);
    inet_aton(cidr, &cidr_addr);

    // Extract prefix length from CIDR notation
    char *slash = strchr(cidr, '/');
    if (slash == NULL) {
        return 0;
    }
    prefix_len = atoi(slash + 1);
    *slash = '\0';

    // Check if IP address is within the CIDR range
    result = (addr.s_addr & htonl(0xFFFFFFFF << (32 - prefix_len))) == (cidr_addr.s_addr & htonl(0xFFFFFFFF << (32 - prefix_len)));

    return result;
}

