    gr = getgrgid(sb.st_gid);
    if (gr == NULL) {
        perror("getgrgid");
        exit(EXIT_FAILURE);
    }
    strcpy(group, gr->gr_name);

    // Open the log file for appending
    fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Log the access attempt
    time_t t = time(NULL);
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", localtime(&t));
    snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), "User: %s, Group: %s, Path: %s\n", user, group, path);

    if (write(fd, log_entry, strlen(log_entry)) == -1) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    // Close the log file
    close(fd);

    // Exit the program
    exit(EXIT

