        perror("Error opening configuration file");
        return 1;
    }

    // Read the IP address from the configuration file
    ssize_t bytes_read = read(config_fd, ip_address, sizeof(ip_address) - 1);
    if (bytes_read == -1) {
        perror("Error reading configuration file");
        close(config_fd);
        return 1;
    }

    // Null-terminate the IP address string
    ip_address[bytes_read] = '\0';

    // Close the configuration file
    close(config_fd);

    // Check if the alerts disabled file exists
    alerts_disabled_fd = open(ALERTS_DISABLED_FILE, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (alerts_disabled_fd == -1) {
        perror("Error creating alerts disabled file");
        return 1;
    }

    // Write the IP address to the alerts disabled file
    write(alerts_disabled_fd, ip_address, strlen(ip_address));

    // Close the alerts disabled file
    close(alerts_disabled_fd);

    printf("Alerts for IP address %s have been temporarily disabled.\n", ip_address);

    return 0;
}

