    if (argc != 3) {
        fprintf(stderr, "Usage: %s <username> <directory_path>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    char *username = argv[1];
    char *directory_path = argv[2];

    // Check if the user is authorized to access the directory
    if (check_access(username, directory_path)) {
        printf("User %s is authorized to access the directory.\n", username);
    } else {
        printf("User %s is not authorized to access the directory.\n", username);
        block_directory(directory_path);
    }

    return 0;
}

