// Function to retrieve the IP address of incoming traffic
char* get_ip_address() {
    char buffer[INET_ADDRSTRLEN];
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);

    // Retrieve the IP address from the socket
    if (getsockname(STDIN_FILENO, (struct sockaddr*)&addr, &len) == 0) {
        inet_ntop(AF_INET, &addr.sin_addr, buffer, INET_ADDRSTRLEN);
        return strdup(buffer);
    }

    return NULL;
}

// Function to check if an IP address is in the list of known malicious IPs
char* is_malicious_ip(char* ip) {
    // Replace this with your own list of known malicious IPs
    char* malicious_ips[] = {"<ip-address>", "<ip-address>", "<ip-address>"};
    int num_malicious_ips = sizeof(malicious_ips) / sizeof(malicious_ips[0]);

    for (int i = 0; i < num_malicious_ips; i++) {
        if (strcmp(ip, malicious_ips[i]) == 0) {
            return "blocked";
        }
    }

    return "allowed";
}

// Main function to block suspicious traffic
int main() {
    char* ip_address;
    char* result;

    // Retrieve the IP address of incoming traffic
    ip_address = get_ip_address();
    if (ip_address == NULL) {
        perror("Error retrieving IP address");
        exit(EXIT_FAILURE);
    }

    // Check if the IP address is in the list of known malicious IPs
    result = is_malicious_ip(ip_address);

    if (strcmp(result, "blocked") == 0) {
        printf("Blocked connection from %s\n", ip_address);
        exit(EXIT_FAILURE);
    } else {
        printf("Allowed connection from %s\n", ip_address);
    }

    free(ip_address);
    return 0;
}

