#define DIRECTORY "<home>"
#define LOG_FILE "/var/log/access.log"

int main() {
    char username[256];
    struct passwd *pw;
    struct stat file_stat;
    int log_fd;

    // Get current user's username
    pw = getpwuid(getuid());
    if (pw == NULL) {
        perror("getpwuid");
        exit(EXIT_FAILURE);
    }
    strcpy(username, pw->pw_name);

    // Check if the directory exists
    if (stat(DIRECTORY, &file_stat) != 0) {
        perror("stat");
        exit(EXIT_FAILURE);
    }

    // Check if the user is allowed to access the directory
    if (strcmp(username, "user") != 0) {
        // Log access attempt
        log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
        if (log_fd == -1) {
            perror("open");
            exit(EXIT_FAILURE);
        }
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "%s attempted to access %s\n", username, DIRECTORY);
        write(log_fd, log_message, strlen(log_message));
        close(log_fd);

        // Block access
        exit(EXIT_FAILURE);
    }

    // Allow access
    printf("Access granted to %s\n", DIRECTORY);

    return 0;
}

