// Function to check if the current user has write permission on the specified directory
int has_write_permission(const char *directory) {
    struct stat sb;
    if (stat(directory, &sb) == -1) {
        perror("Error getting file status");
        return 0;
    }
    return (sb.st_mode & S_IWUSR) != 0;
}

