#define LOG_FILE "/var/log/directory_access.log"
#define DIRECTORY "/restricted"

int main() {
    struct stat sb;
    struct passwd *pw;
    struct group *gr;
    char *username, *groupname;
    int logfd;
    char buffer[256];
    time_t t;
    struct tm *tm_info;

    // Check if the directory exists
    if (stat(DIRECTORY, &sb) != 0) {
        perror("Error accessing directory");
        exit(EXIT_FAILURE);
    }

    // Get current user and group information
    pw = getpwuid(getuid());
    if (pw == NULL) {
        perror("Error getting user information");
        exit(EXIT_FAILURE);
    }
    username = pw->pw_name;

    gr = getgrgid(getgid());
    if (gr == NULL) {
        perror("Error getting group information");
        exit(EXIT_FAILURE);
    }
    groupname = gr->gr_name;

    // Open log file for writing
    logfd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (logfd == -1) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    // Log access attempt
    t = time(NULL);
    tm_info = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), "User: %s, Group: %s, Directory: %s\n", username, groupname, DIRECTORY);

    write(logfd, buffer, strlen(buffer));
    close(logfd);

    // Check if the directory is accessible
    if (access(DIRECTORY, R_OK) == 0) {
        // Directory is accessible, exit with error
        perror("Directory is accessible");
        exit(EXIT_FAILURE);
    } else {
        // Directory is not accessible, exit with success
        exit(EXIT_SUCCESS);
    }
}

#include <stdio.h>
