// Function to check if an IP address is in the list of known suspicious IP addresses
bool is_suspicious_ip(const char* ip, const char* suspicious_ips[], int num_ips) {
    for (int i = 0; i < num_ips; i++) {
        if (strcmp(ip, suspicious_ips[i]) == 0) {
            return true;
        }
    }
    return false;
}

// Function to add a custom IP address to the list of known suspicious IP addresses
void add_suspicious_ip(const char* ip, char* suspicious_ips[], int* num_ips) {
    char* new_ips = (char*)realloc(suspicious_ips, (*num_ips + 1) * sizeof(char*));
    if (new_ips == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }
    suspicious_ips = new_ips;
    suspicious_ips[*num_ips] = strdup(ip);
    (*num_ips)++;
}

// Function to block suspicious traffic based on IP address
void block_suspicious_traffic(const char* ip, const char* suspicious_ips[], int num_ips) {
    if (is_suspicious_ip(ip, suspicious_ips, num_ips)) {
        printf("Blocked suspicious IP address: %s\n", ip);
    } else {
        printf("Allowed IP address: %s\n", ip);
    }
}

// Main function to demonstrate the functionality
int main() {
    char* suspicious_ips[100];
    int num_ips = 0;

    // Add custom IP addresses to the list of known suspicious IP addresses
    add_suspicious_ip("<ip-address>", suspicious_ips, &num_ips);
    add_suspicious_ip("<ip-address>", suspicious_ips, &num_ips);

    // Block traffic based on IP address
    block_suspicious_traffic("<ip-address>", suspicious_ips, num_ips);
    block_suspicious_traffic("<ip-address>", suspicious_ips, num_ips);
    block_suspicious_traffic("<ip-address>", suspicious_ips, num_ips);

    return 0;
}

