// Function to parse packet data
void parse_packet(packet_t *pkt, char *data) {
    memcpy(pkt->src_ip, data, 4);
    memcpy(pkt->dst_ip, data + 4, 4);
    pkt->src_port = ntohs(*(uint16_t*)(data + 8));
    pkt->dst_port = ntohs(*(uint16_t*)(data + 10));
    pkt->protocol = data[12];
    pkt->timestamp = time(NULL);
}

// Function to check if packet matches rule
int matches_rule(packet_t *pkt, rule_t *rule) {
    return (memcmp(pkt->src_ip, rule->src_ip, 4) == 0 &&
            memcmp(pkt->dst_ip, rule->dst_ip, 4) == 0 &&
            pkt->src_port == rule->src_port &&
            pkt->dst_port == rule->dst_port &&
            pkt->protocol == rule->protocol);
}

