int encrypt_file(const char* filename, const char* key) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        printf("Error opening file for reading.\n");
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        printf("Error creating cipher context.\n");
        fclose(fp);
        return -1;
    }

    // Generate a random initialization vector (IV)
    unsigned char iv[16];
    RAND_bytes(iv, 16);

    // Create the encryption cipher
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);

    FILE *out = fopen("encrypted_file.dat", "wb");
    if (!out) {
        printf("Error creating output file.\n");
        EVP_CIPHER_CTX_free(ctx);
        fclose(fp);
        return -1;
    }

    // Write the IV to the output file
    fwrite(iv, 1, 16, out);

    // Encrypt and write the file data
    unsigned char buffer[1024];
    size_t bytes_read;
    while ((bytes_read = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        EVP_EncryptUpdate(ctx, buffer, &bytes_read, buffer, bytes_read);
        fwrite(buffer, 1, bytes_read, out);
    }

    // Finalize the encryption
    unsigned char final_buffer[1024];
    size_t final_bytes;
    EVP_EncryptFinal_ex(ctx, final_buffer, &final_bytes);
    fwrite(final_buffer, 1, final_bytes, out);

    fclose(fp);
    fclose(out);
    EVP_CIPHER_CTX_free(ctx);

    printf("File encrypted successfully.\n");
    return 0;
}

