// Function to retrieve the current IP address of incoming traffic
char* get_ip_address() {
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }
    // Send a packet to an external IP address and port
    // The response will contain the IP address of the sender
    int result = sendto(sock, "", 0, 0, (struct sockaddr*)&addr, len);
    if (result == -1) {
        perror("sendto");
        close(sock);
        exit(EXIT_FAILURE);
    }
    close(sock);
    return inet_ntoa(addr.sin_addr);
}

