// Function to block an IP address
void block_ip(const char* ip) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "iptables -A INPUT -s %s -j DROP", ip);
    system(cmd);
}

// Function to log blocked IP addresses
void log_blocked_ip(const char* ip, time_t timestamp) {
    FILE* log_file = fopen("/var/log/ddos_blocked_ips.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(log_file, "%s: %s\n", ctime(&timestamp), ip);
    fclose(log_file);
}

// Function to update firewall rules
void update_firewall_rules(const char* ip_list) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "iptables -A INPUT -s %s -j DROP", ip_list);
    system(cmd);
}

// Main function
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <IP addresses>\n", argv[0]);
        return 1;
    }

    char* ip_list = argv[1];
    time_t timestamp = time(NULL);

    // Update firewall rules
    update_firewall_rules(ip_list);

    // Log blocked IP addresses
    log_blocked_ip(ip_list, timestamp);

    printf("IP addresses blocked successfully.\n");

    return 0;
}

