// Function to block suspicious traffic based on IP address
// Input: list of IP addresses, list of suspicious IP addresses
// Output: list of IP addresses that are allowed to access the system
int* blockSuspiciousTraffic(char** ipAddresses, int numIPs, char** suspiciousIPs, int numSuspiciousIPs) {
    int* allowedIPs = (int*)malloc(numIPs * sizeof(int));
    int allowedCount = 0;

    for (int i = 0; i < numIPs; i++) {
        int isSuspicious = 0;
        for (int j = 0; j < numSuspiciousIPs; j++) {
            if (strcmp(ipAddresses[i], suspiciousIPs[j]) == 0) {
                isSuspicious = 1;
                break;
            }
        }

        if (!isSuspicious) {
            allowedIPs[allowedCount] = i;
            allowedCount++;
        }
    }

    return allowedIPs;
}

// Main function to demonstrate the usage of the blocking function
int main() {
    char* ipAddresses[] = {"<ip-address>", "<ip-address>", "<ip-address>", "<ip-address>"};
    char* suspiciousIPs[] = {"<ip-address>", "<ip-address>"};
    int numIPs = 4;
    int numSuspiciousIPs = 2;

    int* allowedIPs = blockSuspiciousTraffic(ipAddresses, numIPs, suspiciousIPs, numSuspiciousIPs);

    printf("Allowed IP addresses: ");
    for (int i = 0; i < allowedCount; i++) {
        printf("%s ", ipAddresses[allowedIPs[i]]);
    }
    printf("\n");

    free(allowedIPs);

    return 0;
}

