// Function to check if an IP address is in the allowed CIDR range
int is_allowed_ip(const char* ip, const char* cidr) {
    struct in_addr addr;
    struct in_addr cidr_addr;
    int prefix_len;

    // Convert IP address to network byte order
    inet_aton(ip, &addr);
    inet_aton(cidr, &cidr_addr);

    // Extract prefix length from CIDR notation
    prefix_len = 0;
    char* ptr = strchr(cidr, '/');
    if (ptr != NULL) {
        prefix_len = atoi(ptr + 1);
    }

    // Check if IP address is in the allowed range
    if (prefix_len == 0) {
        return 0;
    }

    // Convert CIDR address to network byte order
    struct in_addr cidr_net;
    cidr_net.s_addr = cidr_addr.s_addr & htonl(0xFFFFFFFF << (32 - prefix_len));

    // Check if IP address is in the allowed range
    return (addr.s_addr & htonl(0xFFFFFFFF << (32 - prefix_len))) == cidr_net.s_addr;
}

