// Function to log messages to the log file
void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

// Function to update all nodes with the new key
void update_nodes(unsigned char *new_key) {
    int i;
    char node_name[32];
    FILE *node_file;
    char key_str[KEY_SIZE * 2 + 1];

    for (i = 0; i < MAX_NODES; i++) {
        sprintf(node_name, "node%d", i);
        node_file = fopen(node_name, "w");
        if (node_file == NULL) {
            log_message("Error opening node file");
            continue;
        }
        for (int j = 0; j < KEY_SIZE; j++) {
            sprintf(key_str + j * 2, "%02x", new_key[j]);
        }
        fprintf(node_file, "%s", key_str);
        fclose(node_file);
    }
}

// Function to check if the current time is within the 24-hour window
int is_time_within_window() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    int seconds = tv.tv_sec;
    int hours = seconds / 3600;
    int minutes = (seconds % 3600) / 60;
    int current_time = hours * 60 + minutes;
    int window_start = 0; // Assuming the window starts at midnight
    int window_end = 24 * 60; // 24 hours in minutes
    return (current_time >= window_start && current_time < window_end);
}

