    snprintf(cmd, sizeof(cmd), "iptables -A INPUT -s %s -j DROP", ip);
    int result = system(cmd);
    if (result == 0) {
        printf("Blocked IP address: %s\n", ip);
        return 0;
    } else {
        printf("Failed to block IP address: %s\n", ip);
        return -1;
    }
}

