        std::lock_guard<std::mutex> lock(mtx);
        if (fileAccessPatterns.find(filePath) != fileAccessPatterns.end()) {
            // Check if the file has been accessed multiple times in a short period
            if (fileAccessPatterns[filePath].size() > 5) {
                return true; // Anomaly detected
            }
        }
        return false;
    }
};

