using namespace std;

// Function to read configuration file and store values in a map
map<string, string> readConfigFile(const string& filename) {
    map<string, string> config;
    ifstream file(filename);
    string line;

    while (getline(file, line)) {
        // Skip empty lines
        if (line.empty()) continue;

        // Split line into key-value pairs
        size_t pos = line.find('=');
        if (pos != string::npos) {
            string key = line.substr(0, pos);
            string value = line.substr(pos + 1);
            config[key] = value;
        }
    }

    return config;
}

// Function to update configuration values based on conditional statements
void updateConfig(map<string, string>& config) {
    // Example conditional statements
    if (config.find("debug") != config.end() && config["debug"] == "true") {
        config["log_level"] = "DEBUG";
    } else {
        config["log_level"] = "INFO";
    }

    if (config.find("verbose") != config.end() && config["verbose"] == "true") {
        config["output_format"] = "verbose";
    } else {
        config["output_format"] = "compact";
    }

    if (config.find("enable_ssl") != config.end() && config["enable_ssl"] == "true") {
        config["ssl_enabled"] = "true";
    } else {
        config["ssl_enabled"] = "false";
    }
}

// Function to write updated configuration back to file
void writeConfigFile(const map<string, string>& config, const string& filename) {
    ofstream file(filename);
    for (auto it = config.begin(); it != config.end(); ++it) {
        file << it->first << "=" << it->second << endl;
    }
}

int main() {
    // Read original configuration file
    map<string, string> config = readConfigFile("config.txt");

    // Update configuration values based on conditional statements
    updateConfig(config);

    // Write updated configuration back to file
    writeConfigFile(config, "config.txt");

    return 0;
}

