// Function to update blacklist from external source
void updateBlacklist(const std::string& filename) {
    std::ifstream file(filename);
    std::string line;
    std::set<std::string> blacklistedIPs;

    if (!file.is_open()) {
        std::cerr << "Error: Could not open blacklist file." << std::endl;
        return;
    }

    while (std::getline(file, line)) {
        std::regex ipRegex("^([0-9]{1,3}\\.){3}[0-9]{1,3}$");
        if (std::regex_match(line, ipRegex)) {
            blacklistedIPs.insert(line);
        }
    }

    file.close();

    // Save updated blacklist to file
    std::ofstream outFile(filename);
    for (const auto& ip : blacklistedIPs) {
        outFile << ip << std::endl;
    }
    outFile.close();
}

// Function to block traffic from blacklisted IPs
void blockTraffic() {
    std::ifstream blacklistFile("blacklist.txt");
    std::string line;
    std::set<std::string> blockedIPs;

    if (!blacklistFile.is_open()) {
        std::cerr << "Error: Could not open blacklist file." << std::endl;
        return;
    }

    while (std::getline(blacklistFile, line)) {
        std::regex ipRegex("^([0-9]{1,3}\\.){3}[0-9]{1,3}$");
        if (std::regex_match(line, ipRegex)) {
            blockedIPs.insert(line);
        }
    }

    blacklistFile.close();

    // Simulate blocking traffic from blacklisted IPs
    for (const auto& ip : blockedIPs) {
        std::cout << "Blocking traffic from IP: " << ip << std::endl;
    }
}

// Main function
int main() {
    std::thread updateThread(updateBlacklist, "external_blacklist.txt");
    std::thread blockThread(blockTraffic);

    updateThread.join();
    blockThread.join();

    return 0;
}

