// Function to read trusted IP addresses from a file
vector<string> readTrustedIPs(const string& filename) {
    vector<string> trustedIPs;
    ifstream file(filename);
    string line;
    while (getline(file, line)) {
        // Remove any leading/trailing whitespace
        line.erase(0, line.find_first_not_of(" \t"));
        line.erase(line.find_last_not_of(" \t") + 1);
        // Check if the line is not empty and contains only IP addresses
        if (!line.empty() && isIP(line)) {
            trustedIPs.push_back(line);
        }
    }
    return trustedIPs;
}

// Function to check if a string is a valid IP address
bool isIP(const string& ip) {
    // Split the string by dots
    vector<string> parts;
    stringstream ss(ip);
    string part;
    while (getline(ss, part, '.')) {
        parts.push_back(part);
    }
    // Check if there are exactly 4 parts
    if (parts.size() != 4) {
        return false;
    }
    // Check if each part is a valid number between 0 and 255
    for (const string& part : parts) {
        if (part.empty() || part[0] == '0' && part.size() > 1) {
            return false;
        }
        int num = stoi(part);
        if (num < 0 || num > 255) {
            return false;
        }
    }
    return true;
}

