using namespace std;

// Function to update the blacklist from a remote server
void updateBlacklist(const string& serverIP, int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        cerr << "Error creating socket" << endl;
        return;
    }

    struct sockaddr_in serverAddr;
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(port);
    inet_pton(AF_INET, serverIP.c_str(), &serverAddr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) == -1) {
        cerr << "Error connecting to server" << endl;
        close(sockfd);
        return;
    }

    string request = "UPDATE_BLACKLIST";
    send(sockfd, request.c_str(), request.length(), 0);

    // Receive the updated blacklist
    string response;
    char buffer[1024];
    int bytesRead = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytesRead > 0) {
        buffer[bytesRead] = '\0';
        response = string(buffer);
    }

    close(sockfd);

    // Update the local blacklist
    updateLocalBlacklist(response);
}

