// Define file access patterns
struct FileAccessPattern {
    string filename;
    int access_count;
    time_t last_access_time;
    bool is_anomalous;
};

// Function to simulate file access
void simulateFileAccess(const vector<string>& files, const vector<string>& users) {
    srand(static_cast<unsigned int>(time(nullptr)));
    unordered_map<string, FileAccessPattern> fileAccessMap;

    for (const auto& file : files) {
        FileAccessPattern pattern;
        pattern.filename = file;
        pattern.access_count = 0;
        pattern.is_anomalous = false;
        fileAccessMap[file] = pattern;
    }

    // Simulate access attempts
    for (int i = 0; i < 100; ++i) {
        string user = users[rand() % users.size()];
        string file = files[rand() % files.size()];
        time_t now = time(nullptr);

        if (fileAccessMap[file].is_anomalous) {
            cout << "Anomaly detected: Unauthorized access attempt by " << user << " to " << file << endl;
            continue;
        }

        fileAccessMap[file].access_count++;
        fileAccessMap[file].last_access_time = now;

        // Check for anomalies based on access frequency
        if (fileAccessMap[file].access_count > 5) {
            fileAccessMap[file].is_anomalous = true;
            cout << "Anomaly detected: High access frequency by " << user << " to " << file << endl;
        }
    }

    // Display results
    for (const auto& entry : fileAccessMap) {
        if (entry.second.is_anomalous) {
            cout << "Blocked access: " << entry.first << endl;
        }
    }
}

int main() {
    vector<string> files = {"config.txt", "database.sql", "logs.txt"};
    vector<string> users = {"admin", "user1", "user2"};

    cout << "Simulating file access with anomaly detection:" << endl;
    simulateFileAccess(files, users);

    return 0;
}

