    for (const auto& e : events) {
        if (e.username == event.username) {
            total_access_count += e.access_count;
            event_count++;
        }
    }
    double avg_access_count = event_count > 0 ? static_cast<double>(total_access_count) / event_count : 0;

    // Calculate the anomaly score based on the access count
    double anomaly_score = abs(event.access_count - avg_access_count) / avg_access_count;

    return anomaly_score;
}

