// Function to count unique IP addresses in a list
int countUniqueIPs(const vector<string>& ips) {
    set<string> uniqueIps;
    for (const string& ip : ips) {
        uniqueIps.insert(ip);
    }
    return uniqueIps.size();
}

// Function to write firewall rules for blocked IPs
void writeFirewallRules(const vector<string>& blockedIps) {
    ofstream rulesFile("/etc/ufw.rules");
    if (!rulesFile.is_open()) {
        cerr << "Error: Could not open /etc/ufw.rules for writing." << endl;
        return;
    }

    rulesFile << "# UFW Rules for Blocked IPs" << endl;
    for (const string& ip : blockedIps) {
        rulesFile << "ufw deny from " << ip << " to any port 80" << endl;
        rulesFile << "ufw deny from " << ip << " to any port 443" << endl;
    }

    rulesFile.close();
    cout << "Firewall rules written successfully to /etc/ufw.rules" << endl;
}

// Function to read IP addresses from a file
vector<string> readIPsFromFile(const string& filename) {
    vector<string> ips;
    ifstream file(filename);
    string line;

    while (getline(file, line)) {
        // Remove any leading/trailing whitespace
        line.erase(0, line.find_first_not_of(" \t"));
        line.erase(line.find_last_not_of(" \t") + 1);

        // Check if the line is not empty and contains an IP address
        if (!line.empty() && isIP(line)) {
            ips.push_back(line);
        }
    }

    return ips;
}

