// Function to search for a file by name in the current directory and subdirectories
vector<string> searchFile(const string& filename) {
    vector<string> results;
    for (const auto& entry : filesystem::recursive_directory_iterator(".")) {
        if (entry.is_regular_file() && entry.path().filename() == filename) {
            results.push_back(entry.path().string());
        }
    }
    return results;
}

// Function to update a configuration file without overwriting the original
bool updateConfigFile(const string& filepath, const string& newContent) {
    ifstream file(filepath);
    if (!file.is_open()) {
        cerr << "Error: Could not open file for reading: " << filepath << endl;
        return false;
    }

    string content((istreambuf_iterator<char>(file)), istreambuf_iterator<char>());
    file.close();

    // Check if the file is empty
    if (content.empty()) {
        cerr << "Warning: File is empty. Skipping update." << endl;
        return true;
    }

    // Replace the content with new content
    ofstream outFile(filepath);
    if (!outFile.is_open()) {
        cerr << "Error: Could not open file for writing: " << filepath << endl;
        return false;
    }

    outFile << newContent;
    outFile.close();

    return true;
}

// Main function
int main() {
    string filename = "config.txt"; // Change this to the name of the configuration file you want to update
    string newContent = "Updated configuration content here."; // Change this to the new content you want to write

    vector<string> results = searchFile(filename);

    if (results.empty()) {
        cerr << "Error: File not found. Please check the name and location of the file." << endl;
        return 1;
    }

    // Update the first found file
    if (!updateConfigFile(results[0], newContent)) {
        cerr << "Error: Failed to update the configuration file." << endl;
        return 1;
    }

    cout << "Configuration file updated successfully!" << endl;

    return 0;
}

