// Function to check if a string is a valid IP address
bool isValidIP(const string& ip) {
    // Split the IP address by dots
    vector<string> parts;
    stringstream ss(ip);
    string part;
    while (getline(ss, part, '.')) {
        parts.push_back(part);
    }

    // Check if there are exactly 4 parts
    if (parts.size() != 4) {
        return false;
    }

    // Check if each part is a valid number between 0 and 255
    for (const string& part : parts) {
        if (part.empty() || part[0] == '0' && part.size() > 1) {
            return false;
        }
        if (part.size() > 1 && part[0] == '0') {
            return false;
        }
        if (part.size() > 3 || part.size() == 0) {
            return false;
        }
        for (char c : part) {
            if (!isdigit(c)) {
                return false;
            }
        }
        int num = stoi(part);
        if (num < 0 || num > 255) {
            return false;
        }
    }

    return true;
}

// Function to write a firewall rule to /etc/ufw/rules.v4
void writeRule(const string& ip) {
    ofstream file("/etc/ufw/rules.v4", ios::app);
    if (!file.is_open()) {
        cerr << "Error opening /etc/ufw/rules.v4 for writing." << endl;
        return;
    }

    // Write the firewall rule
    file << "ufw allow from " << ip << " to any port 80,443" << endl;
    file << "ufw deny from " << ip << " to any" << endl;

    file.close();
}

