const std::string BLOCK_LIST_FILE = "blocked_ips.txt";

// Function to update block list from trusted source
void updateBlockList() {
    std::ifstream trustedSource("trusted_source.txt");
    std::string line;
    std::set<std::string> newBlockList;

    while (std::getline(trustedSource, line)) {
        std::istringstream iss(line);
        std::string ip;
        if (std::getline(iss, ip, ',')) {
            newBlockList.insert(ip);
        }
    }

    std::ofstream blockFile(BLOCK_LIST_FILE);
    for (const auto& ip : newBlockList) {
        blockFile << ip << std::endl;
    }
    blockFile.close();
}

// Function to check if an IP is blocked
bool isBlocked(const std::string& ip) {
    std::ifstream blockFile(BLOCK_LIST_FILE);
    std::string line;
    while (std::getline(blockFile, line)) {
        if (line == ip) {
            return true;
        }
    }
    return false;
}

