// Function to check if an IP address is in the trusted list
bool isTrustedIP(const std::string& ip, const std::set<std::string>& trustedIPs) {
    return trustedIPs.find(ip) != trustedIPs.end();
}

// Function to log blocked IP addresses
void logBlockedIP(const std::string& ip, const std::string& reason, const std::string& logFile) {
    std::ofstream logStream(logFile, std::ios::app);
    if (logStream.is_open()) {
        logStream << "Blocked IP: " << ip << " - Reason: " << reason << std::endl;
        logStream.close();
    }
}

// Function to block IP addresses based on GeoIP data
void blockSuspiciousIPs(const std::vector<std::string>& suspiciousIPs, const std::set<std::string>& trustedIPs, const std::string& logFile) {
    for (const auto& ip : suspiciousIPs) {
        if (!isTrustedIP(ip, trustedIPs)) {
            logBlockedIP(ip, "Not in trusted list", logFile);
            std::cout << "Blocked IP: " << ip << std::endl;
        }
    }
}

