// Function to check for buffer overflow
bool checkBufferOverflow(const char* buffer, size_t bufferSize) {
    // Check if buffer is null
    if (buffer == nullptr) {
        return true;
    }

    // Check if buffer size is greater than the allocated size
    if (bufferSize > 1024) {
        return true;
    }

    // Check for null bytes in the buffer
    for (size_t i = 0; i < bufferSize; ++i) {
        if (buffer[i] == '\0') {
            return true;
        }
    }

    return false;
}

// Function to handle signals
void handleSignal(int signal) {
    std::cout << "Buffer overflow detected! Terminating program." << std::endl;
    exit(1);
}

// Function to allocate memory with protection
void* allocateProtectedMemory(size_t size) {
    void* ptr = nullptr;
    if (mmap(nullptr, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0) == MAP_FAILED) {
        return nullptr;
    }
    return ptr;
}

// Function to detect and prevent buffer overflow
void detectAndPreventBufferOverflow() {
    // Set up signal handler
    signal(SIGSEGV, handleSignal);

    // Allocate memory with protection
    void* buffer = allocateProtectedMemory(1024);
    if (buffer == nullptr) {
        std::cout << "Error allocating memory!" << std::endl;
        return;
    }

    // Check for buffer overflow
    if (checkBufferOverflow(buffer, 1024)) {
        std::cout << "Buffer overflow detected!" << std::endl;
        return;
    }

    // Use the buffer
    std::string data = "This is a test string";
    std::memcpy(buffer, data.c_str(), data.size() + 1);

    // Check for buffer overflow again
    if (checkBufferOverflow(buffer, 1024)) {
        std::cout << "Buffer overflow detected!" << std::endl;
        return;
    }

    std::cout << "Buffer overflow prevented successfully!" << std::endl;
}

int main() {
    detectAndPreventBufferOverflow();
    return 0;
}

