        std::lock_guard<std::mutex> lock(rules_mutex);
        rules = new_rules;
        ruleset_updated = true;
        std::cout << "Ruleset updated successfully." << std::endl;
    }

    void monitorTraffic() {
        std::cout << "Starting traffic monitoring..." << std::endl;
        while (true) {
            if (ruleset_updated) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
                checkForSuspiciousTraffic();
            } else {
                std::this_thread::sleep_for(std::chrono::seconds(5));
            }
        }
    }

    void checkForSuspiciousTraffic() {
        std::lock_guard<std::mutex> lock(rules_mutex);
        for (const auto& rule : rules) {
            if (rule.is_blocked) {
                std::cout << "Blocking traffic from " << rule.source_ip << " to " << rule.destination_ip << " on port " << rule.port << "." << std::endl;
                alertSecurityTeam();
            }
        }
    }

    void alertSecurityTeam() {
        std::cout << "Alert: Potential threat detected. Security team notified." << std::endl;
    }

private:
    std::vector<Rule> rules;
    bool ruleset_updated;
    std::mutex rules_mutex;
};

