// Function to check if a user is authorized to access the repository
bool isAuthorized(const std::string& username, const std::string& password) {
    // Get the current environment variables
    char* env_username = getenv("USERNAME");
    char* env_password = getenv("PASSWORD");

    // Check if the environment variables are set
    if (env_username == nullptr || env_password == nullptr) {
        return false;
    }

    // Compare the provided credentials with the environment variables
    if (username == std::string(env_username) && password == std::string(env_password)) {
        return true;
    }

    // Check if the user is in the authorized list
    std::ifstream authorized_file("/etc/authorized_users.txt");
    std::string line;
    while (std::getline(authorized_file, line)) {
        if (username == line) {
            return true;
        }
    }

    return false;
}

// Main function to demonstrate the authorization function
int main() {
    std::string username = "admin";
    std::string password = "password123";

    // Check if the user is authorized to access the repository
    if (isAuthorized(username, password)) {
        std::cout << "User is authorized to access the repository." << std::endl;
    } else {
        std::cout << "User is not authorized to access the repository." << std::endl;
    }

    return 0;
}

