        return false;
    }
    stringstream ss(ip);
    string segment;
    int count = 0;
    while (getline(ss, segment, '.')) {
        if (segment.empty() || segment.size() > 15) {
            return false;
        }
        if (segment.find_first_not_of('0') == string::npos && segment.size() > 1) {
            return false;
        }
        for (char c : segment) {
            if (!isdigit(c)) {
                return false;
            }
        }
        count++;
    }
    return count == 4;
}

