// Function to check if the current user is authorized to access the directory
bool isAuthorized(const string& directory) {
    // Get the current user's username
    struct passwd* pwd = getpwuid(getuid());
    if (pwd == nullptr) {
        return false;
    }

    // Check if the user is in the authorized list
    ifstream authorizedFile("/etc/authorized_users.txt");
    string line;
    while (getline(authorizedFile, line)) {
        if (line == pwd->pw_name) {
            return true;
        }
    }

    return false;
}

// Function to log access attempts to a file
void logAccessAttempt(const string& directory, const string& username) {
    ofstream logFile("/var/log/directory_access.log", ios::app);
    if (logFile.is_open()) {
        logFile << "[" << string(20, '-') << "]" << " Access attempt to directory: " << directory << " by user: " << username << endl;
        logFile.close();
    }
}

// Function to block access to a directory
void blockAccess(const string& directory) {
    // Check if the current user is authorized
    if (!isAuthorized(directory)) {
        logAccessAttempt(directory, getpwuid(getuid())->pw_name);
        cerr << "Access denied to directory: " << directory << endl;
        exit(1);
    }
}

