// Define a structure to represent user credentials
struct UserCredentials {
    string username;
    string password;
    string role;
};

// Define a map to store valid user credentials
map<string, UserCredentials> validUsers;

// Function to check if a user has valid credentials
bool isValidUser(const string& username, const string& password) {
    auto it = validUsers.find(username);
    if (it != validUsers.end()) {
        return it->second.password == password;
    }
    return false;
}

// Function to check if a user has the appropriate role
bool hasPermission(const string& username, const string& requiredRole) {
    auto it = validUsers.find(username);
    if (it != validUsers.end()) {
        return it->second.role == requiredRole;
    }
    return false;
}

// Function to grant access to the sensitive data repository
void grantAccess(const string& username) {
    if (hasPermission(username, "admin")) {
        cout << "Access granted to the sensitive data repository." << endl;
    } else {
        cout << "Access denied. Insufficient permissions." << endl;
    }
}

// Function to authenticate a user
bool authenticateUser(const string& username, const string& password) {
    if (isValidUser(username, password)) {
        cout << "Authentication successful." << endl;
        return true;
    } else {
        cout << "Authentication failed. Invalid credentials." << endl;
        return false;
    }
}

