// Function to execute a parameterized query using prepared statements
bool executeQuery(sqlite3* db, const string& query, const vector<string>& parameters) {
    sqlite3_stmt* stmt = nullptr;
    int rc = sqlite3_prepare_v2(db, query.c_str(), -1, &stmt, nullptr);
    if (rc != SQLITE_OK) {
        logMessage("Error preparing statement: " + string(sqlite3_errmsg(db)));
        return false;
    }

    // Bind parameters to the prepared statement
    for (size_t i = 0; i < parameters.size(); ++i) {
        rc = sqlite3_bind_text(stmt, i + 1, parameters[i].c_str(), -1, SQLITE_STATIC);
        if (rc != SQLITE_OK) {
            logMessage("Error binding parameter: " + string(sqlite3_errmsg(db)));
            sqlite3_finalize(stmt);
            return false;
        }
    }

    // Execute the query
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        logMessage("Error executing query: " + string(sqlite3_errmsg(db)));
        sqlite3_finalize(stmt);
        return false;
    }

    sqlite3_finalize(stmt);
    return true;
}

