    stringstream ss(ip);
    string octet;
    int count = 0;
    while (getline(ss, octet, '.')) {
        if (octet.empty() || octet[0] == '0' && octet.length() > 1) {
            return false;
        }
        for (char c : octet) {
            if (!isdigit(c)) {
                return false;
            }
        }
        count++;
    }
    return count == 4;
}

