// Function to block traffic from a given IP address
void blockTraffic(const string& ip) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        cerr << "Error creating socket: " << strerror(errno) << endl;
        return;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80); // HTTP port
    addr.sin_addr.s_addr = inet_addr(ip.c_str());

    if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
        cerr << "Error connecting to IP address: " << ip << endl;
        close(sock);
        return;
    }

    // Send a request to the server
    char request[1024];
    snprintf(request, sizeof(request), "GET / HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", ip.c_str());
    send(sock, request, strlen(request), 0);

    // Receive response
    char buffer[1024];
    int bytesReceived = recv(sock, buffer, sizeof(buffer), 0);
    if (bytesReceived > 0) {
        cout << "Blocked traffic from IP address: " << ip << endl;
        cout << "Response: " << buffer << endl;
    }

    close(sock);
}

