class AnomalyDetector {
public:
    struct UserBehavior {
        std::string username;
        std::vector<std::pair<std::string, int>> accessPatterns;
        std::vector<std::pair<std::string, int>> dataAccessPatterns;
        std::vector<std::pair<std::string, int>> networkAccessPatterns;
    };

    AnomalyDetector() {
        srand(static_cast<unsigned int>(std::chrono::system_clock::now().time_since_epoch().count()));
    }

    void addUserBehavior(const std::string& username, const std::vector<std::pair<std::string, int>>& accessPatterns,
                         const std::vector<std::pair<std::string, int>>& dataAccessPatterns,
                         const std::vector<std::pair<std::string, int>>& networkAccessPatterns) {
        userBehaviors[username] = UserBehavior{username, accessPatterns, dataAccessPatterns, networkAccessPatterns};
    }

    bool detectAnomaly(const std::string& username, const std::vector<std::pair<std::string, int>>& currentAccessPatterns) {
        auto& user = userBehaviors[username];
        if (user.accessPatterns.empty()) return false;

        int deviationCount = 0;
        for (const auto& pattern : currentAccessPatterns) {
            auto it = std::find_if(user.accessPatterns.begin(), user.accessPatterns.end(),
                                   [&](const auto& stored) { return stored.first == pattern.first; });
            if (it != user.accessPatterns.end()) {
                if (std::abs(it->second - pattern.second) > 3) {
                    deviationCount++;
                }
            } else {
                deviationCount++;
            }
        }

        return deviationCount > user.accessPatterns.size() / 2;
    }

private:
    std::unordered_map<std::string, UserBehavior> userBehaviors;
};

