// Function to check if a user has access to the repository
bool hasAccess(const string& username, const string& password) {
    // Open the configuration file
    ifstream config("config.txt");
    if (!config.is_open()) {
        return false;
    }

    // Read the configuration file line by line
    string line;
    while (getline(config, line)) {
        // Skip empty lines
        if (line.empty()) {
            continue;
        }

        // Split the line into username and password
        stringstream ss(line);
        string usernameFromConfig, passwordFromConfig;
        getline(ss, usernameFromConfig, ':');
        getline(ss, passwordFromConfig);

        // Check if the provided username and password match the configuration file
        if (username == usernameFromConfig && password == passwordFromConfig) {
            return true;
        }
    }

    // If no match is found, return false
    return false;
}

int main() {
    string username, password;

    // Get input from the user
    cout << "Enter username: ";
    getline(cin, username);
    cout << "Enter password: ";
    getline(cin, password);

    // Check if the user has access to the repository
    if (hasAccess(username, password)) {
        cout << "Access granted!" << endl;
    } else {
        cout << "Access denied!" << endl;
    }

    return 0;
}

