        firewallFile << "ufw deny from " << blockedIp << " to any port 80" << endl;
        firewallFile << "ufw deny from " << blockedIp << " to any port 443" << endl;
    }

    firewallFile.close();
    cout << "Firewall rules updated successfully!" << endl;
}

