using namespace std;

// Function to check if an IP address is already blocked
bool isIPBlocked(const string& ip) {
    ifstream file("/etc/ufw.rules");
    string line;
    while (getline(file, line)) {
        if (line.find(ip) != string::npos) {
            return true;
        }
    }
    return false;
}

// Function to add a firewall rule for an IP address
void addIPBlock(const string& ip) {
    ofstream file("/etc/ufw.rules", ios::app);
    file << "ufw deny from " << ip << " to any port 80\n";
    file.close();
    cout << "IP address " << ip << " has been blocked.\n";
}

// Function to block a list of IP addresses
void blockIPs(const vector<string>& ips) {
    for (const string& ip : ips) {
        if (isIPBlocked(ip)) {
            cout << "IP address " << ip << " is already blocked.\n";
        } else {
            addIPBlock(ip);
        }
    }
}

int main() {
    vector<string> ipAddresses = {"<ip-address>", "<ip-address>", "<ip-address>"};
    blockIPs(ipAddresses);
    return 0;
}

