// Function to manually update the cache file
void updateCache() {
    ifstream file("threat_intelligence.json");
    ofstream cacheFile("threat_intelligence_cache.json");

    if (!file.is_open() || !cacheFile.is_open()) {
        cerr << "Error opening files!" << endl;
        return;
    }

    string line;
    while (getline(file, line)) {
        cacheFile << line << endl;
    }

    file.close();
    cacheFile.close();

    // Log the update to syslog-ng
    syslog(LOG_INFO, "Cache file updated manually.");
}

