// Function to parse CIDR notation and return a vector of IP addresses
vector<string> parseCidr(const string& cidr) {
    vector<string> ips;
    regex cidrPattern("^([0-9]{1,3})\\.([0-9]{1,3})\\.([0-9]{1,3})\\.([0-9]{1,3})/([0-9]{1,2})$");
    smatch match;
    if (regex_match(cidr, match, cidrPattern)) {
        string ip = match[1].str() + "." + match[2].str() + "." + match[3].str() + "." + match[4].str();
        int prefixLength = stoi(match[5].str());
        for (int i = 0; i < 256; i++) {
            string ipWithPrefix = ip + "." + to_string(i);
            if (prefixLength == 0) {
                ips.push_back(ipWithPrefix);
            } else if (prefixLength == 8) {
                ips.push_back(ipWithPrefix);
            } else if (prefixLength == 16) {
                ips.push_back(ipWithPrefix);
            } else if (prefixLength == 24) {
                ips.push_back(ipWithPrefix);
            } else if (prefixLength == 32) {
                ips.push_back(ipWithPrefix);
            }
        }
    }
    return ips;
}

// Function to generate Cisco-like syntax for access control lists
string generateCidrSyntax(const vector<string>& ips) {
    string syntax = "access-list 1 deny ";
    for (const string& ip : ips) {
        syntax += ip + " ";
    }
    syntax += "any";
    return syntax;
}

// Function to log attempts to access the system from blocked IP addresses
void logDdosAttempt(const string& ip) {
    ofstream logFile("ddos_attempts.log", ios::app);
    if (logFile.is_open()) {
        logFile << "[" << getCurrentTime() << "] " << ip << " attempted to access the system." << endl;
        logFile.close();
    }
}

