bool hasAccess(const string& username, const string& directory) {
    if (isRoot()) {
        return true;
    }
    // For simplicity, we assume that only root can access the directory
    return false;
}

// Function to block access to the directory
void blockDirectoryAccess(const string& directory) {
    // Create a lock file to prevent multiple instances of the script
    string lockFile = "/tmp/directory_access_lock";
    ofstream lock(lockFile);
    if (lock.is_open()) {
        lock.close();
    } else {
        cerr << "Error creating lock file: " << lockFile << endl;
        return;
    }

    // Check if the directory exists
    struct stat sb;
    if (stat(directory.c_str(), &sb) != 0) {
        cerr << "Error: Directory does not exist or is inaccessible." << endl;
        return;
    }

    // Check if the directory is a regular file
    if (S_ISREG(sb.st_mode)) {
        cerr << "Error: Directory is a regular file, not a directory." << endl;
        return;
    }

    // Check if the directory is writable by the current user
    if (access(directory.c_str(), W_OK) == 0) {
        cerr << "Error: Directory is writable by the current user." << endl;
        return;
    }

    // Check if the directory is readable by the current user
    if (access(directory.c_str(), R_OK) != 0) {
        cerr << "Error: Directory is not readable by the current user." << endl;
        return;
    }

