// Function to parse a line of input and add it to the rules map
void parseRule(string line) {
    // Split the line into fields using a delimiter
    vector<string> fields;
    string delimiter = " ";
    size_t pos = 0;
    while ((pos = line.find(delimiter)) != string::npos) {
        fields.push_back(line.substr(0, pos));
        line.erase(0, pos + delimiter.length());
    }
    fields.push_back(line);

    // Check if the fields are valid
    if (fields.size() != 6) {
        cout << "Invalid rule format. Expected: protocol src_ip dst_ip src_port dst_port action" << endl;
        return;
    }

    // Create a new rule object
    Rule rule;
    rule.protocol = fields[0];
    rule.src_ip = fields[1];
    rule.dst_ip = fields[2];
    rule.src_port = stoi(fields[3]);
    rule.dst_port = stoi(fields[4]);
    rule.action = fields[5];

    // Add the rule to the map
    string key = rule.protocol + ":" + rule.src_ip + ":" + rule.dst_ip + ":" + to_string(rule.src_port) + ":" + to_string(rule.dst_port);
    rules[key] = rule;
}

