void updateBlacklist(const std::string& filename) {
    std::ifstream file(filename);
    std::string line;
    std::set<std::string> blacklistedIPs;

    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string ip;
        std::getline(iss, ip, ',');
        if (!ip.empty()) {
            blacklistedIPs.insert(ip);
        }
    }

    // Save the updated blacklist to a file
    std::ofstream outFile("blacklist.txt");
    for (const auto& ip : blacklistedIPs) {
        outFile << ip << std::endl;
    }
    outFile.close();
}

