std::string findConfigFile(const std::vector<std::string>& directories, const std::string& filename) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    std::string currentDir = directories[0];
    std::string targetFile = currentDir + "/" + filename;

    // Simulated Annealing parameters
    double temperature = 100.0;
    double coolingRate = 0.95;
    int maxIterations = 1000;

    for (int iteration = 0; iteration < maxIterations; ++iteration) {
        std::string neighborDir = directories[iteration % directories.size()];
        std::string neighborFile = neighborDir + "/" + filename;

        // Calculate cost function (distance from target)
