        // Accept or reject the neighbor based on temperature
        if (dis(gen) < std::exp(-(cost - calculateCost(targetFile, currentDir)) / temperature)) {
            currentDir = neighborDir;
            targetFile = neighborFile;
        }

        // Cool down the temperature
        temperature *= coolingRate;
    }

    return targetFile;
}

// Function to calculate cost function (distance from target)
double calculateCost(const std::string& file1, const std::string& file2) {
    // Calculate the distance between two files based on their paths
    std::string::size_type pos1 = file1.find_last_of("/");
    std::string::size_type pos2 = file2.find_last_of("/");
