    private List<Rule> rules;
    private Map<String, Integer> ruleAccuracy;
    private Map<String, Integer> userFeedback;

    public NetworkTrafficMonitor() {
        this.rules = new ArrayList<>();
        this.ruleAccuracy = new HashMap<>();
        this.userFeedback = new HashMap<>();
    }

    public void addRule(Rule rule) {
        rules.add(rule);
        ruleAccuracy.put(rule.getId(), 0);
    }

    public void updateRule(String ruleId, String feedback) {
        if (ruleAccuracy.containsKey(ruleId)) {
            int accuracy = ruleAccuracy.get(ruleId);
            if (feedback.equals("correct")) {
                ruleAccuracy.put(ruleId, accuracy + 1);
            } else {
                ruleAccuracy.put(ruleId, accuracy - 1);
            }
        }
    }

    public void learnFromFeedback(String ruleId, String feedback) {
        updateRule(ruleId, feedback);
    }

    public boolean isSuspicious(String packet) {
        for (Rule rule : rules) {
            if (rule.matches(packet)) {
                return true;
            }
        }
        return false;
    }

    public void printRules() {
        for (Rule rule : rules) {
            System.out.println(rule.toString());
        }
    }

    public static void main(String[] args) {
        NetworkTrafficMonitor monitor = new NetworkTrafficMonitor();
        monitor.addRule(new Rule("1", "source_ip: <ip-address>"));
        monitor.addRule(new Rule("2", "destination_port: 80"));
        monitor.addRule(new Rule("3", "protocol: TCP"));

        System.out.println("Rules:");
        monitor.printRules();

        monitor.learnFromFeedback("1", "correct");
        System.out.println("Updated rules:");
        monitor.printRules();
    }
}

class Rule {
    private String id;
    private String condition;

    public Rule(String id, String condition) {
        this.id = id;
        this.condition = condition;
    }

    public boolean matches(String packet) {
        return packet.contains(condition);
    }

    public String getId() {
        return id;
    }

    public String toString() {
        return "Rule{" +
                "id='" + id + '\'' +
                ", condition='" + condition + '\'' +
                '}';
    }
